use xiom.io;
use xiom.math;
use xiom.convert.tostring;
fn build_word_list() -> Vec[Str] {
  var words: Vec[Str] = Vec[Str].new();
  words.push("PYTHON");
  words.push("CODING");
  words.push("COMPUTER");
  words.push("PROGRAM");
  words.push("VARIABLE");
  words.push("FUNCTION");
  words.push("ALGORITHM");
  words
}

fn scramble(word: Str) -> Str {
  var chars: Vec[Str] = Vec[Str].new();
  var i = 0;
  while i < word.len() {
    chars.push(to_string_char(word.char_at(i)));
    i = i + 1;
  };

  var result: Vec[Str] = Vec[Str].new();
  while chars.len() > 0 {
    let idx = math.random_range(0, chars.len());
    result.push(chars.get(idx).unwrap());
    chars.remove(idx);
  };

  var scrambled: Str = "";
  var j = 0;
  while j < result.len() {
    scrambled = scrambled + result.get(j).unwrap();
    j = j + 1;
  };
  scrambled
}

fn check(player_guess: Str, answer: Str) -> Bool {
  player_guess == answer
}

fn show_hint(word: Str) -> Str {
  var hint: Str = "";
  hint = hint + to_string_char(word.char_at(0));
  hint = hint + "_";
  let len = word.len();
  io.println(len.to_str());
  hint
}

fn main() -> Int {
  let word_list = build_word_list();
  let pick = word_list.get(math.random_range(0, word_list.len())).unwrap();
  let scrambled = scramble(pick);

  io.println(scrambled.to_str());
  io.println(show_hint(pick));

  let guess = "PYTHON";
  if check(guess, pick) {
    io.println("Correct!");
    io.println(100.to_str());
  } else {
    io.println("Wrong!");
  };

  let pick2 = word_list.get(2).unwrap();
  let scrambled2 = scramble(pick2);
  io.println(scrambled2.to_str());

  return 0;
}
